    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: "Hyponatremia" is defined as a serum sodium level less than:', '["145 mEq/L", "135 mEq/L", "125 mEq/L", "115 mEq/L"]', 1, 'Sodium is the primary determinant of extracellular fluid osmolality.'),
    (v_topic_id, '102: "Pseudohyponatremia" occurs when there are excessive amounts of _____ in the blood.', '["Glucose", "Lipids or Proteins (volume-occupying effect)", "Sodium", "Water"]', 1, 'Standard lab methods measure sodium per total volume of plasma, not per volume of water.'),
    (v_topic_id, '103: In "Hyperglycemia," the serum sodium should be "corrected" by adding _____ for every 100 mg/dL of glucose above normal.', '["1.0 mEq/L", "1.6 to 2.4 mEq/L", "5.0 mEq/L", "10.0 mEq/L"]', 1, 'Glucose acts as an effective osmole, pulling water out of cells and diluting the sodium.'),
    (v_topic_id, '104: "Hypovolemic Hyponatremia" with a URINE SODIUM < 20 mEq/L suggests loss from:', '["Kidneys (diuretics)", "Extra-renal sources (vomiting, diarrhea, third-spacing)", "Brain", "Heart"]', 1, 'The kidneys are correctly trying to conserve sodium in response to volume depletion.'),
    (v_topic_id, '105: "Hypervolemic Hyponatremia" (edema) is characteristic of:', '["SIADH", "Heart failure, Cirrhosis, and Nephrotic syndrome", "Dehydration", "Diabetes insipidus"]', 1, 'Low "effective" circulating volume stimulates ADH despite total body water excess.'),
    (v_topic_id, '106: "SIADH" (Syndrome of Inappropriate Antidiuretic Hormone) causes which pattern?', '["Hypervolemic Hyponatremia", "Euvolemic Hyponatremia", "Hypovolemic Hyponatremia", "Hypernatremia"]', 1, 'The patient appears volume-normal on exam but is water-loaded due to inappropriate ADH.'),
    (v_topic_id, '107: "Serum Osmolality" is calculated as:', '["2[Na] + Glucose/18 + BUN/2.8", "Na + K + Cl", "Glucose + BUN", "2[Na]"]', 0, 'This formula accounts for the most significant osmoles in the blood.'),
    (v_topic_id, '108: "Central Diabetes Insipidus" (lack of ADH) results in:', '["Low Serum Sodium", "High Serum Sodium and Low Urine Osmolality", "High Urine Sodium", "Low Glucose"]', 1, 'The inability to concentrate urine leads to massive free water loss.'),
    (v_topic_id, '109: "Hyperkalemia" is defined as a serum potassium level greater than:', '["3.5 mEq/L", "5.0 to 5.5 mEq/L", "6.5 mEq/L", "7.0 mEq/L"]', 1, 'High potassium is a medical emergency due to the risk of cardiac arrhythmias.'),
    (v_topic_id, '110: "Pseudohyperkalemia" is most commonly caused by:', '["Hemolysis during the blood draw", "Renal failure", "ACE inhibitors", "Diabetes"]', 0, 'Lysis of RBCs releases their high intracellular potassium into the sample.'),
    (v_topic_id, '111: The earliest ECG change in "Hyperkalemia" is:', '["ST elevation", "Peaked T-waves", "Wide QRS", "U-waves"]', 1, 'This occurs as the resting membrane potential becomes less negative.'),
    (v_topic_id, '112: "Hypokalemia" (K < 3.5) can cause which classic ECG finding?', '["Peaked T-waves", "U-waves and ST depression", "Short QT", "Delta waves"]', 1, 'A U-wave is a small wave following the T-wave.'),
    (v_topic_id, '113: Which electrolyte MUST be checked and corrected to treat "Refractory Hypokalemia"?', '["Sodium", "Magnesium", "Calcium", "Chloride"]', 1, 'Low magnesium promotes renal potassium wasting.'),
    (v_topic_id, '114: "Hypercalcemia" (High Calcium) is most commonly caused by:', '["Primary Hyperparathyroidism and Malignancy", "Kidney failure", "Vitamin D deficiency", "Dehydration"]', 0, 'These two causes account for 90% of cases.'),
    (v_topic_id, '115: "Serum Calcium" levels should be "corrected" for low levels of:', '["Globulin", "Albumin", "Sodium", "Glucose"]', 1, 'Approximately 40% of calcium is bound to albumin; low albumin lowers total calcium but not the active ionized fraction.'),
    (v_topic_id, '116: "Hypocalcemia" (Low Calcium) with a HIGH "Phosphate" level is characteristic of:', '["Vitamin D deficiency", "Chronic Kidney Disease (CKD) or Hypoparathyroidism", "Pancreatitis", "Bone cancer"]', 1, 'Failure to excrete phosphate or lack of PTH leads to this pattern.'),
    (v_topic_id, '117: "Chvostek sign" (facial twitching) and "Trousseau sign" (carpal spasm) are clinical indicators of:', '["Hyperkalemia", "Hypocalcemia", "Hypomagnesemia", "Both B and C"]', 3, 'Both low calcium and low magnesium increase neuromuscular excitability.'),
    (v_topic_id, '118: "Hypermagnesemia" (High Magnesium) is almost always seen in the setting of:', '["Excessive intake plus Renal Failure", "Diarrhea", "Alcoholism", "Pregnancy"]', 0, 'The kidneys are usually very efficient at excreting excess magnesium.'),
    (v_topic_id, '119: "Hypophosphatemia" (Low Phosphate) in hospitalized patients is often a sign of:', '["Refeeding Syndrome", "Renal failure", "Hypoparathyroidism", "Bone metastasis"]', 0, 'Insulin release during feeding shifts phosphate into cells for ATP production.'),
    (v_topic_id, '120: "Blood Urea Nitrogen" (BUN) to "Creatinine" ratio > 20:1 suggests:', '["Intrinsic renal damage", "Prerenal azotemia (dehydration or low flow)", "Postrenal obstruction", "Normal function"]', 1, 'The kidney reabsorbs urea with water in dehydration, while creatinine is not reabsorbed.'),
    (v_topic_id, '121: "Serum Creatinine" is a breakdown product of _____ and is used to estimate _____:', '["Fat; Liver function", "Muscle (Creatine); Glomerular Filtration Rate (GFR)", "Sugar; Insulin", "Protein; Diet"]', 1, 'It is filtered by the glomerulus and not significantly reabsorbed.'),
    (v_topic_id, '122: "Fractional Excretion of Sodium" (FeNa) < 1% indicates:', '["Prerenal azotemia (kidneys are functional and saving sodium)", "Acute Tubular Necrosis (ATN)", "Glomerulonephritis", "Obstructive uropathy"]', 0, 'A low FeNa proves the tubules are still able to concentrate and reabsorb sodium.'),
    (v_topic_id, '123: "Fractional Excretion of Sodium" (FeNa) > 2% indicates:', '["Prerenal states", "Acute Tubular Necrosis (ATN - tubules are damaged and wasting sodium)", "Heart failure", "Cirrhosis"]', 1, 'Damage to the tubular cells prevents effective sodium reabsorption.'),
    (v_topic_id, '124: "Urine Osmolality" > 500 mOsm/kg in an oliguric patient suggests:', '["Prerenal Azotemia", "Acute Tubular Necrosis", "Diabetes Insipidus", "Normal function"]', 0, 'The kidney is appropriately concentrating the urine to save water.'),
    (v_topic_id, '125: "Urine Osmolality" \u2248 300 mOsm/kg (similar to plasma) is called:', '["Hypersthenuria", "Isosthenuria (indicates intrinsic renal damage like ATN)", "Hyposthenuria", "Normal"]', 1, 'The kidney has lost the ability to concentrate or dilute the urine.'),
    (v_topic_id, '126: "Aspartate Aminotransferase" (AST) and "Alanine Aminotransferase" (ALT) are markers of:', '["Liver synthetic function", "Hepatocellular injury (necrosis/inflammation)", "Bile duct obstruction", "Gallstones"]', 1, 'They are enzymes released when liver cells are damaged.'),
    (v_topic_id, '127: An "AST to ALT ratio" of > 2:1 is classically suggestive of:', '["Viral Hepatitis", "Alcoholic Liver Disease", "Nonalcoholic Fatty Liver Disease (NAFLD)", "Gallstones"]', 1, 'Alcohol suppresses ALT synthesis (due to B6 deficiency), keeping the ratio high.'),
    (v_topic_id, '128: "Alanine Aminotransferase" (ALT) is considered _____ specific to the liver than AST.', '["Less", "More", "Equally", "Not"]', 1, 'AST is also found in heart, muscle, and RBCs.'),
    (v_topic_id, '129: "Alkaline Phosphatase" (ALP) is elevated in which two primary conditions?', '["Liver disease and Kidney disease", "Cholestasis (bile duct obstruction) and Bone turnover", "Diabetes and Heart failure", "Anemia and Sepsis"]', 1, 'High ALP with a normal GGT suggests bone origin.'),
    (v_topic_id, '130: "Gamma-Glutamyl Transferase" (GGT) is used to confirm that an elevated ALP is of _____ origin.', '["Bone", "Hepatobiliary", "Heart", "Placental"]', 1, 'GGT is not found in bone.'),
    (v_topic_id, '131: "Unconjugated (Indirect) Bilirubin" elevation is seen in:', '["Bile duct obstruction", "Hemolysis and Gilbert Syndrome", "Cirrhosis", "Gallstones"]', 1, 'The liver has not yet processed the bilirubin.'),
    (v_topic_id, '132: "Conjugated (Direct) Bilirubin" elevation is seen in:', '["Hemolysis", "Cholestasis (Gallstones, Tumor) and Dubin-Johnson Syndrome", "Gilbert syndrome", "Newborn jaundice"]', 1, 'The bilirubin has been processed but cannot be excreted into the bile.'),
    (v_topic_id, '133: Which of the following is the best measure of the LIVER''S SYNTHETIC function?', '["ALT/AST", "ALP", "Albumin and Prothrombin Time (PT/INR)", "Bilirubin"]', 2, 'The liver produces albumin and clotting factors; their levels drop as synthetic capacity fails.'),
    (v_topic_id, '134: "Hypoalbuminemia" can cause edema by decreasing serum:', '["Hydrostatic pressure", "Oncotic pressure", "Glucose", "Sodium"]', 1, 'Water leaks out of the vessels because there aren''t enough proteins to hold it in.'),
    (v_topic_id, '135: "Ammonia" levels are monitored in patients with:', '["Heart failure", "Hepatic Encephalopathy", "Kidney stones", "Pneumonia"]', 1, 'The failing liver cannot convert ammonia to urea.'),
    (v_topic_id, '136: "Serum Amylase" and "Lipase" are used to diagnose:', '["Liver failure", "Acute Pancreatitis", "Gallstones", "Diabetes"]', 1, 'Lipase is more specific and stays elevated longer than amylase.'),
    (v_topic_id, '137: "Uric Acid" elevation (Hyperuricemia) is the risk factor for:', '["Gout and Urate kidney stones", "Rheumatoid arthritis", "Diabetes", "Osteoporosis"]', 0, 'High levels lead to crystal deposition in joints.'),
    (v_topic_id, '138: "Creatine Kinase" (CK) is a marker of _____ damage.', '["Liver", "Muscle (Rhabdomyolysis or Myocardial Infarction)", "Brain", "Kidney"]', 1, 'CK-MB is specific for heart; CK-MM for skeletal muscle.'),
    (v_topic_id, '139: "Lactate Dehydrogenase" (LDH) is a non-specific marker of:', '["Cell turnover / Tissue damage (Hemolysis, Lymphoma, Infarction)", "Digestion", "Blood sugar", "Salt balance"]', 0, 'It is found in almost all tissues.'),
    (v_topic_id, '140: "B-type Natriuretic Peptide" (BNP) is released from the _____ in response to _____:', '["Kidneys; low flow", "Heart ventricles; stretch/pressure (Heart Failure)", "Liver; toxin", "Lungs; hypoxia"]', 1, 'It is a sensitive marker for diagnosing congestive heart failure.'),
    (v_topic_id, '141: A patient with a VERY high BNP (> 400) and dyspnea likely has:', '["Pneumonia", "Acute Congestive Heart Failure", "Asthma", "Pulmonary Embolism"]', 1, 'BNP helps distinguish cardiac from pulmonary causes of shortness of breath.'),
    (v_topic_id, '142: "Cardiac Troponin" (I or T) is the most specific marker for:', '["Heart failure", "Myocardial Necrosis (Acute Myocardial Infarction)", "Pericarditis", "Hypertension"]', 1, 'Troponins are proteins specific to cardiac muscle cells.'),
    (v_topic_id, '143: "Troponin" levels usually begin to rise _____ hours after a heart attack.', '["1", "3 to 6", "12 to 24", "48"]', 1, 'They remain elevated for up to 7-10 days.'),
    (v_topic_id, '144: "Glycated Hemoglobin" (HbA1c) targets for most diabetics are usually less than:', '["10%", "7%", "5%", "4%"]', 1, 'Lowering A1c reduces the risk of microvascular complications.'),
    (v_topic_id, '145: "Fast Blood Glucose" (FBG) > _____ mg/dL on two separate occasions is diagnostic of Diabetes.', '["100", "126", "140", "200"]', 1, 'Normal fasting glucose is < 100 mg/dL.'),
    (v_topic_id, '146: "Thyroid Stimulating Hormone" (TSH) is HIGH and "Free T4" is LOW in:', '["Primary Hyperthyroidism", "Primary Hypothyroidism", "Secondary Hypothyroidism", "Thyroiditis"]', 1, 'The pituitary is trying to stimulate a failing thyroid gland.'),
    (v_topic_id, '147: "Thyroid Stimulating Hormone" (TSH) is LOW and "Free T4" is HIGH in:', '["Primary Hypothyroidism", "Primary Hyperthyroidism (e.g., Graves Disease)", "Pituitary tumor", "Iodine deficiency"]', 1, 'High thyroid hormone levels provide negative feedback to the pituitary.'),
    (v_topic_id, '148: "Total Cholesterol" calculation: LDL + HDL + (Triglycerides / _____):', '["2", "5", "10", "20"]', 1, 'The Friedewald equation.'),
    (v_topic_id, '149: "Triglyceride" levels > 1000 mg/dL significantly increase the risk of:', '["Heart attack", "Acute Pancreatitis", "Liver failure", "Stroke"]', 1, 'Extremely high fats can cause inflammation of the pancreas.'),
    (v_topic_id, '150: "Low Density Lipoprotein" (LDL) is known as _____ cholesterol.', '["Good", "Bad (associated with atherosclerosis)", "Neutral", "Essential"]', 1, 'High levels are a primary target for statin therapy.'),
    (v_topic_id, '151: "High Density Lipoprotein" (HDL) is known as _____ cholesterol.', '["Good (helps remove cholesterol from arteries)", "Bad", "Waste", "Synthetic"]', 0, 'Higher levels are generally considered cardioprotective.'),
    (v_topic_id, '152: "C-peptide" level is used to distinguish between:', '["Type 1 and Type 2 Diabetes (or Exogenous vs Endogenous insulin)", "Anemia and Leukemia", "Liver and Heart failure", "Gout and Pseudogout"]', 0, 'C-peptide is released 1:1 with endogenous insulin; it is absent in Type 1 diabetics and injected insulin.'),
    (v_topic_id, '153: "Procalcitonin" is most useful in which clinical setting?', '["Managing an ICU patient with suspected bacterial sepsis", "Screening for cancer", "Diagnosing heart failure", "Checking for diabetes"]', 0, 'It helps guide the initiation and duration of antibiotic therapy.'),
    (v_topic_id, '154: "D-dimer" has a very high "Negative Predictive Value," meaning if it is normal:', '["The patient has a clot", "A Pulmonary Embolism or DVT is highly unlikely", "The patient has cancer", "The lab is wrong"]', 1, 'It is best used to "rule out" disease in low-risk patients.'),
    (v_topic_id, '155: "Serum Protein Electrophoresis" (SPEP) with a "Polyclonal" increase suggests:', '["Multiple Myeloma", "Chronic inflammation or Liver disease", "Leukemia", "MGUS"]', 1, 'Many different types of antibodies are being produced.'),
    (v_topic_id, '156: "Serum Protein Electrophoresis" (SPEP) with a "Monoclonal" spike (M-spike) suggests:', '["Infection", "Plasma cell dyscrasia (e.g., Multiple Myeloma)", "Normal state", "Allergy"]', 1, 'One clone of plasma cells is over-producing a single antibody.'),
    (v_topic_id, '157: "Albumin-to-Creatinine Ratio" (ACR) in a spot urine sample is used to screen for:', '["Kidney stones", "Diabetic Nephropathy (Microalbuminuria)", "Infection", "Bladder cancer"]', 1, 'Early kidney damage is marked by the leakage of small amounts of albumin.'),
    (v_topic_id, '158: "Microalbuminuria" is defined as a urine albumin of:', '["< 30 mg/day", "30 to 300 mg/day", "> 300 mg/day", "> 1000 mg/day"]', 1, 'Standard dipsticks only detect protein > 300 mg/day (macroalbuminuria).'),
    (v_topic_id, '159: "Proteinuria" of > 3.5 g/day is the hallmark of:', '["Nephritic Syndrome", "Nephrotic Syndrome", "Cystitis", "Renal stones"]', 1, 'Associated with edema, hypoalbuminemia, and hyperlipidemia.'),
    (v_topic_id, '160: "Hemoglobinuria" (blood in urine) without RBCs on microscopy suggests:', '["Infection", "Intravascular hemolysis (hemoglobin) or Rhabdomyolysis (myoglobin)", "Kidney stones", "Tumor"]', 1, 'The dipstick detects the heme pigment, not the whole cell.'),
    (v_topic_id, '161: "Specific Gravity" of urine measures:', '["Concentration (density) of the urine", "pH", "Sugar", "Protein"]', 0, 'It correlates roughly with osmolality.'),
    (v_topic_id, '162: "Urine pH" of > 8.0 in the setting of a UTI suggests infection with:', '["E. coli", "Urease-producing bacteria (e.g., Proteus mirabilis)", "Staph", "Strep"]', 1, 'Urease splits urea into ammonia, raising the pH and promoting "Staghorn" calculi.'),
    (v_topic_id, '163: "Nitrites" on a urine dipstick are a sign of:', '["Dehydration", "Gram-negative bacterial infection (e.g., E. coli)", "Kidney stones", "Pregnancy"]', 1, 'Many bacteria convert nitrates to nitrites.'),
    (v_topic_id, '164: "Leukocyte Esterase" on a urine dipstick indicates:', '["Blood", "White blood cells (Pyuria)", "Protein", "Glucose"]', 1, 'It is an enzyme released by neutrophils.'),
    (v_topic_id, '165: "Hyaline Casts" in the urine are:', '["Pathognomonic for disease", "Often normal (seen in dehydration or exercise)", "A sign of infection", "A sign of cancer"]', 1, 'They are composed of Tamm-Horsfall mucoprotein.'),
    (v_topic_id, '166: "Red Blood Cell (RBC) Casts" are pathognomonic for:', '["Cystitis", "Glomerulonephritis", "Kidney stones", "Prostatitis"]', 1, 'They prove the bleeding is coming from the glomerulus.'),
    (v_topic_id, '167: "White Blood Cell (WBC) Casts" suggest:', '["Cystitis", "Pyelonephritis (kidney infection) or Tubulointerstitial nephritis", "Tumor", "Stones"]', 1, 'They prove the inflammation is within the kidney parenchyma.'),
    (v_topic_id, '168: "Fatty Casts" and "Oval Fat Bodies" (Maltese cross appearance) are seen in:', '["Glomerulonephritis", "Nephrotic Syndrome", "ATN", "Pyelonephritis"]', 1, 'Lipiduria occurs when the glomerular basement membrane is highly permeable.'),
    (v_topic_id, '169: "Granular Casts" (often "Muddy Brown") are the classic finding in:', '["Prerenal azotemia", "Acute Tubular Necrosis (ATN)", "Nephrotic syndrome", "Postrenal obstruction"]', 1, 'They represent sloughed tubular epithelial cells.'),
    (v_topic_id, '170: "Waxy Casts" are associated with:', '["Acute infection", "Chronic Renal Failure", "Exercise", "Dehydration"]', 1, 'They represent long-standing stasis in dilated tubules.'),
    (v_topic_id, '171: "Synovial Fluid" with > 50,000 WBCs and > 75% Neutrophils is characteristic of:', '["Osteoarthritis", "Septic Arthritis", "Gout", "Rheumatoid Arthritis"]', 1, 'This is a surgical emergency.'),
    (v_topic_id, '172: "Gout" crystals are _____ and show _____ birefringence under polarized light.', '["Needle-shaped; Negative (yellow when parallel)", "Rhomboid; Positive (blue when parallel)", "Square; None", "Round; Positive"]', 0, 'They are composed of monosodium urate.'),
    (v_topic_id, '173: "Pseudogout" (CPPD) crystals are _____ and show _____ birefringence.', '["Needle; Negative", "Rhomboid-shaped; Weakly Positive (blue when parallel)", "Star; Negative", "Invisible"]', 1, 'They are composed of calcium pyrophosphate dihydrate.'),
    (v_topic_id, '174: "CSF" with High Protein, Low Glucose, and High Neutrophils indicates:', '["Viral Meningitis", "Bacterial Meningitis", "Fungal Meningitis", "Multiple Sclerosis"]', 1, 'Bacteria consume glucose and trigger a robust neutrophil response.'),
    (v_topic_id, '175: "CSF" with Normal/High Protein, Normal Glucose, and High Lymphocytes indicates:', '["Bacterial Meningitis", "Viral Meningitis", "Brain abscess", "Stroke"]', 1, 'Viruses typically trigger a lymphocytic response without consuming glucose.'),
    (v_topic_id, '176: "Xanthochromia" (yellow color) in the CSF is diagnostic of:', '["Meningitis", "Subarachnoid Hemorrhage (representing breakdown of RBCs)", "Jaundice", "High protein"]', 1, 'It is seen if the sample is taken hours after the hemorrhage.'),
    (v_topic_id, '177: "Oligoclonal Bands" in the CSF (not present in serum) are a key finding in:', '["Brain tumor", "Multiple Sclerosis", "Meningitis", "Dementia"]', 1, 'They represent intrathecal immunoglobulin production.'),
    (v_topic_id, '178: "Light''s Criteria" are used to distinguish _____ from _____ pleural effusions.', '["Infected; Sterile", "Transudates; Exudates", "Blood; Water", "Air; Fluid"]', 1, 'Exudates meet at least one of the three criteria (Protein or LDH ratios).'),
    (v_topic_id, '179: A "Transudative" pleural effusion (Light''s criteria negative) is usually caused by:', '["Pneumonia", "Heart Failure, Cirrhosis, or Nephrotic Syndrome", "Cancer", "Pulmonary Embolism"]', 1, 'Systemic factors alter the hydrostatic or oncotic pressures.'),
    (v_topic_id, '180: An "Exudative" pleural effusion (Light''s criteria positive) is usually caused by:', '["Pneumonia, Malignancy, or Pulmonary Embolism", "Heart failure", "Dehydration", "High salt"]', 0, 'Local factors alter the permeability of the pleural surface.'),
    (v_topic_id, '181: "Pleural Fluid Glucose" < 60 mg/dL is commonly seen in:', '["Parapneumonic effusion, Malignancy, or Rheumatoid arthritis", "Heart failure", "Cirrhosis", "Trauma"]', 0, 'Bacteria or highly active cells consume the glucose.'),
    (v_topic_id, '182: "Serum Anion Gap" = 140 - (100 + 10) = 30. This is:', '["Normal", "High Anion Gap Metabolic Acidosis", "Low Anion Gap", "Error"]', 1, 'A gap of 30 is significantly elevated.'),
    (v_topic_id, '183: "Hypermagnesemia" can cause which clinical finding?', '["Hyperreflexia", "Loss of Deep Tendon Reflexes", "Tachypnea", "High BP"]', 1, 'High magnesium acts as a muscle relaxant and CNS depressant.'),
    (v_topic_id, '184: "Hypomagnesemia" is common in which patient population?', '["Alcoholics and those on long-term Diuretics or Proton Pump Inhibitors (PPIs)", "Diabetics", "Athletes", "Children"]', 0, 'Poor intake and renal/GI losses are common.'),
    (v_topic_id, '185: "Hypernatremia" (Na > 145) is almost always due to a deficit in:', '["Salt", "Free Water", "Protein", "Glucose"]', 1, 'It usually occurs in patients who cannot access water or have no thirst drive.'),
    (v_topic_id, '186: Rapid correction of "Hyponatremia" (> 8-10 mEq in 24h) carries a risk of:', '["Cerebral edema", "Osmotic Demyelination Syndrome (Central Pontine Myelinolysis)", "Heart failure", "Seizures"]', 1, 'Water is pulled out of brain cells too quickly.'),
    (v_topic_id, '187: Rapid correction of "Hypernatremia" carries a risk of:', '["Osmotic demyelination", "Cerebral Edema", "Kidney failure", "Anemia"]', 1, 'Water rushes into brain cells too quickly.'),
    (v_topic_id, '188: "Fractional Excretion of Urea" (FeUrea) is used instead of FeNa in patients taking:', '["Aspirin", "Diuretics", "Insulin", "Statins"]', 1, 'Diuretics interfere with sodium handling but have less effect on urea handling.'),
    (v_topic_id, '189: "Myoglobinuria" (from Rhabdomyolysis) is toxic to the:', '["Liver", "Renal Tubules (causes ATN)", "Heart", "Lungs"]', 1, 'It precipitates in the tubules and causes direct oxidative damage.'),
    (v_topic_id, '190: "Creatine Kinase" (CK) levels in Rhabdomyolysis are typically:', '["< 100", "> 10,000", "Normal", "Undetectable"]', 1, 'Massive muscle breakdown releases huge amounts of CK.'),
    (v_topic_id, '191: "Hypokalemia" causes the "resting membrane potential" of cells to become:', '["More positive", "More negative (hyperpolarized)", "Unstable", "Neutral"]', 1, 'This makes it harder for the cell to fire an action potential, causing weakness.'),
    (v_topic_id, '112: "Serum Anion Gap" = 140 - (105 + 24) = 11. This is:', '["Normal", "High", "Low", "Mixed"]', 0, 'The normal range is typically 8-12.'),
    (v_topic_id, '193: "BUN" can be falsely elevated by:', '["Steroid use, High protein diet, or Upper GI bleed", "Drinking water", "Exercise", "Smoking"]', 0, 'These increase the nitrogen load independently of kidney function.'),
    (v_topic_id, '194: "BUN" can be low in:', '["Malnutrition and severe Liver Disease", "Renal failure", "Dehydration", "High protein diet"]', 0, 'The liver is responsible for urea synthesis.'),
    (v_topic_id, '195: "Creatinine Clearance" (CrCl) is a slightly over-estimation of GFR because creatinine is:', '["Filtered and Reabsorbed", "Filtered and Secreted (about 10-20%)", "Not filtered", "Produced in the kidney"]', 1, 'The secretion makes the clearance look higher than the true filtration rate.'),
    (v_topic_id, '196: "Cystatin C" is an alternative marker for GFR that is less affected by:', '["Age", "Muscle mass and Diet", "Gender", "Race"]', 1, 'It is more accurate in patients with extremes of body habitus.'),
    (v_topic_id, '197: "Acute Kidney Injury" (AKI) is defined by a rise in creatinine of _____ within 48 hours.', '["0.1 mg/dL", "0.3 mg/dL", "1.0 mg/dL", "2.0 mg/dL"]', 1, 'KDIGO criteria.'),
    (v_topic_id, '198: "Liver Function Tests" (LFTs) is a misnomer; which of the following is an actual test of FUNCTION?', '["ALT", "AST", "International Normalized Ratio (INR)", "ALP"]', 2, 'Clotting factor synthesis is a core liver function.'),
    (v_topic_id, '199: "Gilbert Syndrome" is a benign condition characterized by isolated, mild:', '["Conjugated hyperbilirubinemia", "Unconjugated hyperbilirubinemia (often triggered by stress/fasting)", "High ALT", "High ALP"]', 1, 'It is due to a reduction in UGT1A1 enzyme activity.'),
    (v_topic_id, '200: "Crigler-Najjar Syndrome" is a more severe form of _____ than Gilbert syndrome.', '["Direct hyperbilirubinemia", "Indirect hyperbilirubinemia", "Hepatitis", "Cirrhosis"]', 1, 'Type 1 is fatal without liver transplant; Type 2 is less severe.');
